data.content:
MSTest **does not have** `Assert.IsGreaterThan` or `Assert.IsInRange` — those don't exist. Here's what to use instead:

## MSTest Options for Boundary/Comparison Checks

| Need | Use |
|------|-----|
| Value in range | `Assert.IsTrue(value >= lo && value <= hi)` |
| Greater than | `Assert.IsTrue(value > threshold)` |
| Equality (float) | `Assert.AreEqual(expected, actual, delta)` |

For better readability, use **Fluent Assertions** (`value.Should().BeInRange(...)`) or write helpers. But with stock MSTest:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Contoso.Scoring;

namespace Contoso.Scoring.Tests;

[TestClass]
public class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calc = new();

    // CalculatePercentage tests
    [TestMethod]
    public void CalculatePercentage_PerfectScore_Returns100()
    {
        var result = _calc.CalculatePercentage(10, 10);
        Assert.AreEqual(100.0, result, 0.001);
    }

    [TestMethod]
    public void CalculatePercentage_ZeroCorrect_Returns0()
    {
        var result = _calc.CalculatePercentage(0, 10);
        Assert.AreEqual(0.0, result, 0.001);
    }

    [TestMethod]
    public void CalculatePercentage_ResultAlwaysBetween0And100()
    {
        var result = _calc.CalculatePercentage(7, 10);
        Assert.IsTrue(result >= 0.0 && result <= 100.0,
            $"Expected [0,100] but got {result}");
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(0, 0));
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(11, 10));
    }

    // GetGrade boundary tests
    [DataTestMethod]
    [DataRow(90.0, "A")]
    [DataRow(89.999, "B")]
    [DataRow(80.0, "B")]
    [DataRow(79.999, "C")]
    [DataRow(70.0, "C")]
    [DataRow(69.999, "D")]
    [DataRow(60.0, "D")]
    [DataRow(59.999, "F")]
    public void GetGrade_AtBoundaries_ReturnsExpected(double pct, string expected)
    {
        Assert.AreEqual(expected, _calc.GetGrade(pct));
    }

    // NormalizeScore tests
    [TestMethod]
    public void NormalizeScore_NeverExceeds100()
    {
        var result = _calc.NormalizeScore(150, 100);
        Assert.IsTrue(result <= 100.0,
            $"Expected <= 100 but got {result}");
    }

    [TestMethod]
    public void NormalizeScore_ResultIsNonNegative()
    {
        var result = _calc.NormalizeScore(0, 50);
        Assert.IsTrue(result >= 0.0,
            $"Expected >= 0 but got {result}");
    }

    [TestMethod]
    public void NormalizeScore_NegativeRaw_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calc.NormalizeScore(-1, 100));
    }
}
```

**Key takeaways:**
- Use `Assert.AreEqual(expected, actual, delta)` for floating-point equality (the 3rd arg is tolerance)
- Use `Assert.IsTrue(condition, message)` for range/comparison checks — include a message for clear failures
- Use `Assert.ThrowsException<T>()` for boundary violation exceptions
- `[DataTestMethod]` + `[DataRow]` is great for testing multiple boundary values
